effect.shader:
const int N = 7;
const float OFF[7] = float[7](-3.0, -2.0, -1.0, 0.0, 1.0, 2.0, 3.0);
const float WT[7]  = float[7](0.071, 0.131, 0.190, 0.216, 0.190, 0.131, 0.071);

vec2 espelhar(vec2 uv) {
    int a = int(axis);
    if (a == 0) return vec2(2.0 * center - uv.x, uv.y);
    if (a == 1) return vec2(uv.x, 2.0 * center - uv.y);
    if (a == 2) return 2.0 * vec2(center) - uv;
    return vec2(2.0 * center - uv.x, 2.0 * center - uv.y);
}

void main() {
    vec2 direction = (acPass == 0) ? vec2(1.0, 0.0) : vec2(0.0, 1.0);
    vec2 passo = direction * acTexelSize * (blurRadius * acEscalaDePixel);

    vec4 soma = vec4(0.0);
    for (int i = 0; i < N; i++) {
        vec2 uv = acScreenNorm + passo * OFF[i];
        vec4 c = (acPass == 0) ? texture(inputImg, uv) : texture(hblur, uv);
        soma += c * WT[i];
    }

    if (acPass == 0) {
        fragColor = soma;
        return;
    }

    vec4 espelhado = texture(hblur, espelhar(acScreenNorm));
    vec4 direto    = soma;
    fragColor = mix(direto, espelhado, mixAmount);
}
